// ============================================================================
// mini_soc_pkg -- SoC configuration generated by socgen from socgen/specs/mini_soc.yaml
// CI-sized instance of the common SoC spec
// Do not edit: change the spec and run socgen again.
// ============================================================================
`ifndef MINI_SOC_PKG_SV
`define MINI_SOC_PKG_SV
package mini_soc_pkg;
  // ---------------- sizes ----------------
  localparam int NM  = 3;       // AXI masters
  localparam int NS  = 6;       // NoC slave ports
  localparam int NCH = 4;       // interleaved memory channels (ports 0..NCH-1)
  localparam int S_DEF = NS;       // decode miss: DECERR from the NoC default slave
  localparam int MESH_ROWS = 2, MESH_COLS = 2;
  localparam int NI_CYCLES = 1, ROUTER_CYCLES = 1, LINK_CYCLES = 1;
  localparam real CLK_PERIOD_NS = 2.0;
  localparam int ID_WIDTH = 4;

  // ---------------- masters ----------------
  localparam int M_CPU = 0;
  localparam int M_DISP = 1;
  localparam int M_DMA = 2;

  // ---------------- NoC slave ports ----------------
  localparam int S_DDR0 = 0;
  localparam int S_DDR1 = 1;
  localparam int S_DDR2 = 2;
  localparam int S_DDR3 = 3;
  localparam int S_SRAM = 4;   // memory
  localparam int S_PERIPH = 5;   // apb_bridge
  localparam int S_APB = 5;
  localparam int S_DDR_FIRST = 0, DDR_NCH = 4;

  localparam string M_NAME [NM] = '{ "cpu", "disp", "dma" };
  localparam string S_NAME [NS+1] = '{ "ddr0", "ddr1", "ddr2", "ddr3", "sram", "periph", "decerr" };
  localparam string S_KIND [NS+1] = '{ "channel", "channel", "channel", "channel", "memory", "apb_bridge", "default" };

  // ---------------- address map ----------------
  localparam logic [31:0] DDR_BASE = 32'h80000000, DDR_SIZE = 32'h0FFFFFFF + 1;
  localparam int DDR_GRANULE_BITS = 12, DDR_CH_BITS = 2, DDR_HASH = 1;
  localparam int DDR_ACCESS = 12;   // lpddr5

  localparam logic [31:0] SRAM_BASE = 32'h00000000, SRAM_SIZE = 32'h00010000;
  localparam logic [31:0] PERIPH_BASE = 32'h10000000, PERIPH_SIZE = 32'h00010000;

  localparam logic [31:0] S_BASE [NS] = '{ 32'h80000000, 32'h80000000, 32'h80000000, 32'h80000000, 32'h00000000, 32'h10000000 };
  localparam int S_ACCESS [NS] = '{ 12, 12, 12, 12, 1, 4 };

  // ddr: channel = off[13:12] ^ off[15:14], off = a - DDR_BASE
  function automatic int mini_ddr_channel(logic [31:0] a);
    logic [31:0] off = a - DDR_BASE;
    logic [1:0] c = off[13:12] ^ off[15:14];
    return int'(c);
  endfunction
  // channel-local address: the offset with the channel-select bits removed
  function automatic logic [31:0] mini_ddr_local(logic [31:0] a);
    logic [31:0] off = a - DDR_BASE;
    return ((off >> 14) << 12) | (off & 32'h00000FFF);
  endfunction
  function automatic int dram_channel(logic [31:0] a); return mini_ddr_channel(a); endfunction
  function automatic logic [31:0] dram_local(logic [31:0] a); return mini_ddr_local(a); endfunction
  function automatic int mini_dram_channel(logic [31:0] a); return mini_ddr_channel(a); endfunction
  function automatic logic [31:0] mini_dram_local(logic [31:0] a); return mini_ddr_local(a); endfunction

  // address -> NoC slave port (S_DEF on a miss)
  function automatic int mini_decode(logic [31:0] a);
    if (a >= DDR_BASE && a - DDR_BASE < 33'(DDR_SIZE))
      return S_DDR_FIRST + mini_ddr_channel(a);
    if (a >= SRAM_BASE && a - SRAM_BASE < SRAM_SIZE) return S_SRAM;
    if (a >= PERIPH_BASE && a - PERIPH_BASE < PERIPH_SIZE) return S_PERIPH;
    return S_DEF;
  endfunction

  // ---------------- APB slots (periph) ----------------
  localparam logic [31:0] APB_BASE = 32'h10000000;
  localparam int APB_SLOT_BITS = 4;          // PADDR[15:12]
  localparam int APB_NSLOTS = 16;            // slots in the window
  localparam int APB_SLOT_GPIO = 0;   // 0x10000000 ip GPIO
  localparam int APB_SLOT_UART = 1;   // 0x10001000 ip UART
  localparam int APB_SLOT_EXT = 2;   // 0x10002000 vip apb vip
  localparam int APB_SLOT_IOMMU0_REGS = 3;   // 0x10003000 regs iommu
  localparam int APB_NMAPPED = 4;
  localparam int APB_MAPPED_SLOT [APB_NMAPPED] = '{ 0, 1, 2, 3 };
  localparam string APB_SLOT_NAME [APB_NMAPPED] = '{ "gpio", "uart", "ext", "iommu0_regs" };
  // ID register value per mapped slot (0: no ID register)
  localparam logic [31:0] APB_SLOT_ID [APB_NMAPPED] = '{ 32'h47500200, 32'h55410200, 32'h00000000, 32'h494F0100 };
  function automatic int apb_slot_of(logic [31:0] a);
    return int'((a - APB_BASE) >> 12);
  endfunction
  // mapped-slot index of an address in the APB window, -1 when the slot is empty
  function automatic int apb_mapped_of(logic [31:0] a);
    int sl = apb_slot_of(a);
    foreach (APB_MAPPED_SLOT[i]) if (APB_MAPPED_SLOT[i] == sl) return i;
    return -1;
  endfunction

  // ---------------- mesh placement and latency ----------------
  localparam int M_X [NM] = '{ 0, 1, 0 };
  localparam int M_Y [NM] = '{ 0, 0, 1 };
  localparam int S_X [NS] = '{ 0, 0, 1, 1, 0, 1 };
  localparam int S_Y [NS] = '{ 1, 1, 1, 1, 0, 0 };
  // XY hops, master m to slave port s
  localparam int HOPS [NM][NS] = '{
    '{ 1, 1, 2, 2, 0, 1 },   // cpu
    '{ 2, 2, 1, 1, 1, 0 },   // disp
    '{ 0, 0, 1, 1, 1, 2 }   // dma
  };
  // request path (one way + IOMMU TLB hit), response path, ideal single-beat
  // zero-load read latency (request + access + response), in clock cycles
  localparam int REQ_LAT [NM][NS] = '{
    '{ 5, 5, 7, 7, 3, 5 },
    '{ 9, 9, 7, 7, 7, 5 },
    '{ 3, 3, 5, 5, 5, 7 }
  };
  localparam int RSP_LAT [NM][NS] = '{
    '{ 5, 5, 7, 7, 3, 5 },
    '{ 7, 7, 5, 5, 5, 3 },
    '{ 3, 3, 5, 5, 5, 7 }
  };
  localparam int IDEAL_LAT [NM][NS] = '{
    '{ 22, 22, 26, 26, 7, 14 },
    '{ 28, 28, 24, 24, 13, 12 },
    '{ 18, 18, 22, 22, 11, 18 }
  };
  // one way NoC latency: 2*NI + (hops+1)*ROUTER + hops*LINK
  function automatic int noc_lat(int mi, int si);
    return 2 * NI_CYCLES + (HOPS[mi][si] + 1) * ROUTER_CYCLES + HOPS[mi][si] * LINK_CYCLES;
  endfunction
  function automatic int mini_noc_lat(int mi, int si); return noc_lat(mi, si); endfunction

  // ---------------- IOMMUs ----------------
  localparam int NIOMMU = 1;
  localparam int IOMMU_IOMMU0 = 0;   // disp, TLB 32 entries
  localparam int M_IOMMU [NM] = '{ -1, 0, -1 };   // -1: none
  localparam int IOMMU_TLB_HIT [NIOMMU > 0 ? NIOMMU : 1] = '{ 2 };
  function automatic int iommu_of(int mi); return M_IOMMU[mi]; endfunction

  // ---------------- master kind ----------------
  localparam bit M_IS_RTL [NM] = '{ 1'b0, 1'b0, 1'b0 };

  // ---------------- QoS ----------------
  localparam int M_PRIORITY [NM] = '{ 8, 12, 1 };
  localparam string M_QOS [NM] = '{ "nrt", "rt", "be" };
  localparam int M_LAT_TARGET [NM] = '{ 80, 120, 0 };   // 0: none
  localparam int M_BW_MBPS [NM] = '{ 0, 400, 0 };

  // one address per (master, slave port) inside that master's private slice
  localparam logic [31:0] PATH_ADDR [NM][NS] = '{
    '{ 32'h80000000, 32'h80001000, 32'h80002000, 32'h80003000, 32'h00000000, 32'h10000000 },
    '{ 32'h85555040, 32'h8555B040, 32'h85557040, 32'h85556040, 32'h00005000, 32'h10000000 },
    '{ 32'h8AAAA080, 32'h8AAAB080, 32'h8AAAD080, 32'h8AAAC080, 32'h0000A000, 32'h10000000 }
  };
  localparam bit HAS_UNMAPPED = 1;
  localparam logic [31:0] UNMAPPED_ADDR = 32'h00010000;
endpackage
`endif
